class Handler
{
    public virtual string Name => "base";
    public string Kind => "handler";
}

sealed class LtiHandler : Handler
{
    public override string Name => "lti";
    public new string Kind => "lti-handler";
}

Handler h = new LtiHandler();
Console.WriteLine(h.Name); // lti — virtual dispatch
Console.WriteLine(h.Kind); // handler — hidden, not dispatched
